.ds-project-pagination > span { display: block; width: 7px; height: 7px; background: #9b9da5; border-radius: 999px; transition: width .4s var(--ease, cubic-bezier(.16, 1, .3, 1)), background .4s; }
.ds-project-pagination > span.ds-is-active { width: 27px; background: var(--accent, #1460ed); }
@media (max-width: 900px) { .ds-project-carousel { --project-width: 86vw; --project-gap: 12px; } }
@media (max-width: 900px) { .ds-project-caption { left: 28px; right: 28px; bottom: 26px; } }
@media (max-width: 540px) { .ds-project-slide { aspect-ratio: 6 / 5; } }
@media (max-width: 540px) { .ds-project-caption { left: 22px; right: 22px; bottom: 22px; } }
@media (max-width: 540px) { .ds-project-caption h3 { font-size: 30px; } }
@media (max-width: 540px) { .ds-project-caption span { font-size: 12px; margin-top: 9px; max-width: 24ch; } }
@media (max-width: 540px) { .ds-project-controls { gap: 10px; } }
@media (max-width: 540px) { .ds-project-glass .ds-form-one, .ds-project-glass .ds-form-two { width: 53%; } }
@media (max-width: 540px) { .ds-project-orbit .ds-form-one { width: 80%; } }
@media (max-width: 540px) { .ds-project-orbit .ds-form-two { width: 60%; border-width: 13px; } }
@media (max-width: 540px) { .ds-project-orbit .ds-form-three { width: 35%; } }
@media (prefers-reduced-transparency: reduce) { .ds-project-glass .ds-form-two { background: #d4eeff; backdrop-filter: none; } }

@media (prefers-reduced-motion: reduce) { .ds-preview, .ds-preview * { animation: none !important; transition: none !important; } .ds-button:active, .ds-text-link:hover svg { transform: none; } }
